    }
}
package infra;

import domain.FxQuote;

import java.io.IOException;
import java.io.InputStream;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

/** Thin wrapper around the vendor quote CLI. One process per call. */
public class FxqClient {
    private final Path bin;
    private final long timeoutSeconds;

    public FxqClient(Path bin, long timeoutSeconds) {
        this.bin = bin;
        this.timeoutSeconds = timeoutSeconds;
    }

    /** Raw stdout line for {@code fxq rate PAIR DATE}. */
    public String rate(String pair, LocalDate date) {
        return rate(pair, date, false);
    }

    /** Raw stdout line for {@code fxq rate PAIR DATE --src 3} (settlement source). */
    public String settlementQuote(String pair, LocalDate date) {
        return rate(pair, date, true);
    }

    private String rate(String pair, LocalDate date, boolean settlementSource) {
        List<String> cmd = new ArrayList<>();
        cmd.add(bin.toString());
        cmd.add("rate");
        cmd.add(pair);
        cmd.add(date.toString());
        if (settlementSource) {
            cmd.add("--src");
            cmd.add("3");
        }
        return run(cmd);
    }

    /** Parses one quote line: {@code PAIR YYYY-MM-DD RATE [~N]}. */
    public static FxQuote parse(String line) {
        String[] t = line.trim().split("\\s+");
        if (t.length < 3) {
            throw new IllegalArgumentException("unexpected quote line: " + line);
        }
        boolean lagged = t.length > 3 && t[3].startsWith("~");
        return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]), lagged);
    }

    private String run(List<String> cmd) {
        try {
            Process p = new ProcessBuilder(cmd).start();
            byte[] out;
            byte[] err;
            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
                out = o.readAllBytes();
                err = e.readAllBytes();
            }
            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
                p.destroyForcibly();
                throw new FxqException("timeout", cmd);
            }
            if (p.exitValue() != 0) {
                throw new FxqException(new String(err, StandardCharsets.UTF_8).trim(), cmd);
            }
            String line = new String(out, StandardCharsets.UTF_8).trim();
            if (line.isEmpty()) throw new FxqException("empty output", cmd);
            return line;
        } catch (IOException e) {
            throw new FxqException("exec failed: " + e.getMessage(), cmd);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new FxqException("interrupted", cmd);
        }
    }

    public static class FxqException extends RuntimeException {
        public FxqException(String code, List<String> cmd) {
            super("fxq failed [" + code + "]: " + String.join(" ", cmd));
        }
    }
}
package util;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** KRW arithmetic shared by settlement and reporting. */
public final class Money {
    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);

    private Money() {}

    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
        return amount.multiply(rate)
                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
                .longValueExact();
    }

    /** Commission on gross KRW; partner contract truncates fractional won. */
    public static long fee(long grossKrw, int feeBps) {
        if (grossKrw <= 0 || feeBps <= 0) return 0;
        return BigDecimal.valueOf(grossKrw)
                .multiply(BigDecimal.valueOf(feeBps))
                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
                .longValueExact();
    }

    public static String won(long krw) {
        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(krw);
    }

    public static String rate(BigDecimal rate) {
        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(rate);
    }
}
package util;

import java.util.ArrayList;
import java.util.List;

/** Minimal CSV line splitter (comma separated, double-quote escaping). */
public final class Csv {
    private Csv() {}

    public static List<String> split(String line) {
        List<String> out = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        boolean quoted = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (quoted) {
                if (c == '"' && i + 1 < line.length() && line.charAt(i + 1) == '"') {
                    cur.append('"');
                    i++;
                } else if (c == '"') {
                    quoted = false;
                } else {
                    cur.append(c);
                }
            } else if (c == '"') {
                quoted = true;
            } else if (c == ',') {
                out.add(cur.toString());
                cur.setLength(0);
            } else {
                cur.append(c);
            }
        }
        out.add(cur.toString());
        return out;
    }

    public static boolean isDataLine(String line) {
        String t = line.trim();
        return !t.isEmpty() && !t.startsWith("#");
    }
}
