/** Per-transaction lines of one partner in the period, by KST date then transaction id. */
public List<TxnLine> detail(String partnerId, LocalDate from, LocalDate to) {
    return transactions(from, to).stream()
            .filter(t -> t.partnerId().equals(partnerId))
            .sorted(Comparator.comparing(TxnLine::date).thenComparing(TxnLine::txnId))
            .toList();
}

/** Every settled transaction of active partners in the period, in feed order. Same rules as {@link #settle}. */
private List<TxnLine> transactions(LocalDate from, LocalDate to) {
    List<TxnLine> out = new ArrayList<>();
    for (Transaction t : data.transactions()) {
        LocalDate d = dates.dateOf(t.approvedAt());
        if (d.isBefore(from) || d.isAfter(to)) continue;
        Partner p = data.partner(t.partnerId()).orElse(null);
        if (p == null || !p.active()) continue;
        out.add(convert(t, d));
    }
    return out;
}

private TxnLine convert(Transaction t, LocalDate businessDate) {
    FxQuote quote = rates.quote(t.currency(), businessDate);
    BigDecimal rate = rates.settlementRate(t.currency(), businessDate);
    long krw = Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    Optional<BigDecimal> publicRate = quote.lagged() ? Optional.empty() : Optional.of(rate);
    return new TxnLine(t.partnerId(), t.id(), businessDate, t.currency(), t.signedAmount(), krw, publicRate);
}

